template:
// Next strictly greater element to the RIGHT, as an index (or -1).
// Flip the comparison for 'smaller'; scan from the right for 'to the LEFT'.
vector<int> nextGreater(const vector<int>& a) {
    int n = a.size();
    vector<int> ans(n, -1);
    vector<int> st;                       // indices; a[st] strictly decreasing
    for (int i = 0; i < n; ++i) {
        while (!st.empty() && a[st.back()] < a[i]) {   // a[i] beats the top
            ans[st.back()] = i;             // top has found its answer
            st.pop_back();
        }
        st.push_back(i);                   // i now waits for its own answer
    }
    return ans;                            // leftovers stay -1
}

// Largest rectangle in a histogram: for each bar, nearest smaller on both sides.
// width = right[i] - left[i] - 1, area = h[i] * width.
long long largestRectangle(const vector<int>& h) {
    int n = h.size();
    vector<int> left(n, -1), right(n, n), st;
    for (int i = 0; i < n; ++i) {
        while (!st.empty() && h[st.back()] >= h[i]) { right[st.back()] = i; st.pop_back(); }
        left[i] = st.empty() ? -1 : st.back();
        st.push_back(i);
    }
    long long best = 0;
    for (int i = 0; i < n; ++i) best = max(best, 1LL * h[i] * (right[i] - left[i] - 1));
    return best;
}
